INSERT OR IGNORE INTO `question_templates` (`id`, `category`, `stage`, `question`, `intent`, `keywords`, `source_name`, `source_url`, `source_fetched_at`, `created_at`) VALUES
('q-why-now', '転職理由', 'behavioral', '今回の転職で実現したいことは何ですか？今の環境では難しいと感じたきっかけも教えてください。', '転職理由の一貫性と、次の環境に求める条件を確認する。', '["転職","キャリア","改善"]', 'MVP editorial', NULL, NULL, 1767225600000),
('q-project-overview', 'プロジェクト', 'all', '直近のプロジェクトを、目的・規模・期間・あなたの担当範囲に分けて説明してください。', '経歴の事実関係と、本人が担った責任の大きさを確認する。', '["プロジェクト","担当","チーム","SaaS"]', 'MVP editorial', NULL, NULL, 1767225600000),
